<script setup lang="ts">
import { computed } from 'vue';
export type PaymentBrand = 'visa'|'mastercard'|'amex'|'apple-pay'|'google-pay'|'paypal'|'discover'|'generic';
const props=withDefaults(defineProps<{brand?:PaymentBrand;size?:number;ariaLabel?:string}>(),{brand:'generic',size:38});
